## Defines the durations of the partials of an additive synthesis note. The fundamental lasts for#"duracionTotal". The rest of the partials' durations are equal to the total duration minus the#corresponding atack time.def duraciones(comienzos_csd, duracionTotal):		duraciones	= []		for x in comienzos_csd:		una_duracion = x		una_duracion = duracionTotal - x		duraciones.append(una_duracion)	return duraciones